const defaultState = {
  language: "en",
  role: "citizen",
  map: { noPower: 4, restored: 1 },
  reports: [
    { id: "VV-2026-1042", category: "Low voltage", location: "Pedakakani", status: "In Progress", createdAt: "Today, 10:24", assigned: "R. Mahesh" },
    { id: "VV-2026-0981", category: "Power outage", location: "Namburu Road", status: "Resolved", createdAt: "28 Oct, 18:40", assigned: "S. Babu" }
  ]
};

function loadState() {
  try {
    const saved = JSON.parse(localStorage.getItem("vidyuthVaaniState"));
    return { ...defaultState, ...saved, map: { ...defaultState.map, ...(saved?.map || {}) }, reports: saved?.reports || defaultState.reports };
  } catch {
    return structuredClone(defaultState);
  }
}

let state = loadState();
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];

function saveState() { localStorage.setItem("vidyuthVaaniState", JSON.stringify(state)); }

function showToast(title, detail = "") {
  const toast = document.createElement("div");
  toast.className = "toast";
  toast.innerHTML = `<span>✓</span><div><strong>${title}</strong><small>${detail}</small></div>`;
  $("#toastRegion").append(toast);
  setTimeout(() => toast.remove(), 4200);
}

function navigate(view) {
  $$("[data-view-panel]").forEach(panel => panel.classList.toggle("active", panel.dataset.viewPanel === view));
  $$(".nav-item").forEach(item => item.classList.toggle("active", item.dataset.view === view));
  window.scrollTo({ top: 0, behavior: "smooth" });
  history.replaceState(null, "", `#${view}`);
}

function applyLanguage() {
  const dictionary = translations[state.language];
  $$('[data-copy]').forEach(element => {
    const text = dictionary[element.dataset.copy];
    if (text) element.textContent = text;
  });
  $$('[data-copy-placeholder]').forEach(element => {
    const text = dictionary[element.dataset.copyPlaceholder];
    if (text) element.placeholder = text;
  });
  const toggleSpans = $$("#languageToggle span");
  toggleSpans[0].classList.toggle("active", state.language === "en");
  toggleSpans[1].classList.toggle("active", state.language === "te");
  document.documentElement.lang = state.language === "te" ? "te" : "en";
}

function renderReports() {
  const list = $("#recentReportsList");
  if (!state.reports.length) {
    list.innerHTML = '<div class="empty-state"><strong>No reports yet</strong><span>Your submitted faults will appear here.</span></div>';
  } else {
    list.innerHTML = state.reports.slice(0, 3).map(report => {
      const statusClass = report.status === "Resolved" || report.status === "Closed" ? "resolved" : report.status === "In Progress" ? "progress" : "";
      return `<article class="report-row"><div><strong>${report.category} · ${report.id}</strong><small>${report.location} · ${report.createdAt}</small></div><span class="status-pill ${statusClass}">${report.status}</span></article>`;
    }).join("");
  }
  renderIncidentTable();
}

function calculateConfidence() {
  return Math.max(0, Math.min(100, state.map.noPower * 25 - state.map.restored * 20 - 48));
}

function renderMap() {
  const confidence = calculateConfidence();
  $("#noPowerCount").textContent = state.map.noPower;
  $("#restoredCount").textContent = state.map.restored;
  $("#mapMainCount").textContent = state.map.noPower;
  $("#mapConfidence").textContent = `${confidence}%`;
  $("#confidenceBar").style.width = `${confidence}%`;
  $("#nearbyReportCount").textContent = state.map.noPower;
  $("#gridConfidence").textContent = `${100 - confidence}%`;
  $("#operatorPedakakaniConfidence").textContent = `${confidence}% outage confidence`;
  $("#operatorPedakakaniReports").textContent = state.map.noPower;
  const activity = [
    { title: "Power restored reported near Main Road", time: "8 minutes ago" },
    { title: "No power reported near ZP School", time: "21 minutes ago" },
    { title: "Local report confidence recalculated", time: "24 minutes ago" }
  ];
  $("#mapActivity").innerHTML = activity.map(item => `<div class="activity-item"><strong>${item.title}</strong><small>${item.time}</small></div>`).join("");
}

function reportMapStatus(type) {
  if (type === "noPower") state.map.noPower += 1;
  else state.map.restored += 1;
  saveState(); renderMap();
  showToast(type === "noPower" ? "Outage report added" : "Restoration report added", "Your local map has been updated.");
}

function submitFault(event) {
  event.preventDefault();
  const id = `VV-2026-${String(Math.floor(1000 + Math.random() * 9000))}`;
  const report = {
    id,
    category: $("#faultCategory").value,
    location: $("#faultLocation").value.trim(),
    phone: $("#faultPhone").value.trim(),
    description: $("#faultDescription").value.trim(),
    status: "Reported",
    createdAt: "Just now",
    assigned: "Unassigned"
  };
  state.reports.unshift(report);
  if (report.category === "Power outage") state.map.noPower += 1;
  saveState(); renderReports(); renderMap();
  event.target.reset();
  $("#faultLocation").value = "Pedakakani, Guntur";
  showToast(`Report ${id} submitted`, "Track it from your overview. The operator queue has been updated.");
  setTimeout(() => navigate("home"), 900);
}

function analyseBill(units, amount) {
  const nextSlab = units <= 100 ? 101 : units <= 200 ? 201 : units <= 300 ? 301 : units <= 400 ? 401 : Math.ceil((units + 1) / 100) * 100 + 1;
  const distance = Math.max(0, nextSlab - units);
  const lower = nextSlab - 100;
  const rate = units > 0 ? amount / units : 0;
  $("#usageUnits").textContent = units;
  $("#usageHeadline").textContent = `${distance} unit${distance === 1 ? "" : "s"} before the next slab`;
  $("#usageExplanation").textContent = `Your current consumption is inside the ${lower}–${nextSlab - 1} unit tariff slab.`;
  $("#averageRate").textContent = `₹${rate.toFixed(2)} / unit`;
  $("#savingEstimate").textContent = `₹${Math.round(amount * 0.12)} / month`;
  $(".usage-ring").style.setProperty("--value", Math.min(100, Math.round((units / (nextSlab - 1)) * 100)));
  renderAppliances(units);
}

function renderAppliances(units = 182) {
  const appliances = [
    ["Refrigerator", 28], ["Fans", 24], ["Air conditioner", 21], ["Water pump", 17], ["Other", 10]
  ];
  $("#applianceBars").innerHTML = appliances.map(([name, percent]) => `<div class="appliance-row"><strong>${name}</strong><span><i style="width:${percent}%"></i></span><b>${Math.round(units * percent / 100)}u</b></div>`).join("");
}

const schemes = {
  domestic: [
    { name: "PM Surya Ghar: Muft Bijli Yojana", type: "Rooftop solar", match: "Likely match", description: "Support for eligible residential households installing rooftop solar through the national portal.", benefit: "Up to ₹78,000", action: "Aadhaar, electricity bill, bank details" },
    { name: "Gruha Jyothi Scheme", type: "Domestic supply", match: "Check locally", description: "Free electricity support may apply based on state rules, household eligibility and monthly consumption.", benefit: "Up to 200 units", action: "Aadhaar, ration card, recent bill", maybe: true }
  ],
  bpl: [
    { name: "Gruha Jyothi Scheme", type: "Priority household", match: "Likely match", description: "Eligible low-income domestic households may receive monthly electricity support under applicable state rules.", benefit: "Up to 200 units", action: "Aadhaar, BPL card, recent bill" },
    { name: "PM Surya Ghar: Muft Bijli Yojana", type: "Rooftop solar", match: "Check locally", description: "Residential rooftop solar subsidy with installation and technical eligibility requirements.", benefit: "Up to ₹78,000", action: "Aadhaar, electricity bill, bank details", maybe: true }
  ],
  agriculture: [
    { name: "Agriculture Free Power", type: "Agricultural connection", match: "Likely match", description: "Power supply support for eligible agricultural connections, subject to local DISCOM schedules and verification.", benefit: "Scheduled free supply", action: "Land record, Aadhaar, service number" }
  ]
};

function renderSchemes(category = "domestic", units = 182) {
  const available = schemes[category] || schemes.domestic;
  $("#schemeResults").innerHTML = available.map(scheme => `<article class="scheme-card ${scheme.maybe ? "maybe" : ""}"><header><div><h2>${scheme.name}</h2><p>${scheme.type}</p></div><span class="match-badge">${scheme.match}</span></header><p>${scheme.description}</p><div class="scheme-benefit"><div><small>Possible benefit</small><strong>${scheme.benefit}</strong></div><div><small>Documents to prepare</small><strong>${scheme.action}</strong></div></div></article>`).join("");
  if (category === "domestic" && units > 200) {
    const badge = $(".scheme-card:nth-child(2) .match-badge");
    if (badge) badge.textContent = "Usage above guide";
  }
}

function renderIncidentTable() {
  const rows = state.reports.filter(report => report.status !== "Closed").slice(0, 7);
  $("#incidentTableBody").innerHTML = rows.map((report, index) => {
    const statusClass = report.status === "Resolved" ? "resolved" : report.status === "In Progress" ? "progress" : "";
    return `<tr><td><strong>${report.id}</strong><small>${report.createdAt}</small></td><td><strong>${report.category}</strong></td><td>${report.location}</td><td><span class="status-pill ${statusClass}">${report.status}</span></td><td>${report.assigned || "Unassigned"}</td><td><button class="table-action" type="button" data-advance-report="${index}" aria-label="Advance incident status">›</button></td></tr>`;
  }).join("");
  $("#openIncidentMetric").textContent = rows.filter(report => !["Resolved", "Closed"].includes(report.status)).length;
}

function advanceReport(index) {
  const rows = state.reports.filter(report => report.status !== "Closed").slice(0, 7);
  const target = rows[index];
  if (!target) return;
  const stages = ["Reported", "Acknowledged", "In Progress", "Resolved", "Closed"];
  target.status = stages[Math.min(stages.length - 1, stages.indexOf(target.status) + 1)];
  if (target.status === "Acknowledged" && target.assigned === "Unassigned") target.assigned = "R. Mahesh";
  saveState(); renderReports();
  showToast(`${target.id} updated`, `Status changed to ${target.status}.`);
}

function switchRole(role) {
  state.role = role;
  saveState();
  $("#citizenApp").hidden = role !== "citizen";
  $("#operatorApp").hidden = role !== "operator";
  $(".sidebar").hidden = role !== "citizen";
  $(".app-shell").style.gridTemplateColumns = role === "operator" ? "1fr" : "";
  $("#roleName").textContent = role === "citizen" ? "Citizen" : "Operator";
  $("#avatarInitials").textContent = role === "citizen" ? "LK" : "OP";
  closeModals();
  renderIncidentTable();
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function closeModals() { $$(".modal-backdrop").forEach(modal => modal.hidden = true); }

function bindEvents() {
  $$(".nav-item").forEach(button => button.addEventListener("click", () => navigate(button.dataset.view)));
  $$('[data-go]').forEach(button => button.addEventListener("click", () => navigate(button.dataset.go)));
  $("#languageToggle").addEventListener("click", () => { state.language = state.language === "en" ? "te" : "en"; saveState(); applyLanguage(); });
  $("#roleButton").addEventListener("click", () => $("#roleModal").hidden = false);
  $("#voiceButton").addEventListener("click", () => $("#voiceModal").hidden = false);
  $$('[data-close-modal]').forEach(button => button.addEventListener("click", closeModals));
  $$(".modal-backdrop").forEach(modal => modal.addEventListener("click", event => { if (event.target === modal) closeModals(); }));
  $$("[data-role]").forEach(button => button.addEventListener("click", () => switchRole(button.dataset.role)));
  $$(".choice").forEach(button => button.addEventListener("click", () => {
    $$(".choice").forEach(choice => choice.classList.remove("active"));
    button.classList.add("active");
    $("#faultCategory").value = button.dataset.category;
  }));
  $("#faultForm").addEventListener("submit", submitFault);
  $("#detectLocation").addEventListener("click", () => {
    $("#faultLocation").value = "Pedakakani, Guntur · 16.3729, 80.4924";
    showToast("Location detected", "GPS coordinates have been attached.");
  });
  $("#faultPhoto").addEventListener("change", event => {
    const file = event.target.files[0];
    if (file) $("#faultUploadZone strong").textContent = file.name;
  });
  $("#noPowerButton").addEventListener("click", () => reportMapStatus("noPower"));
  $("#restoredButton").addEventListener("click", () => reportMapStatus("restored"));
  $("#billForm").addEventListener("submit", event => {
    event.preventDefault();
    analyseBill(Number($("#billUnits").value), Number($("#billAmount").value));
    showToast("Bill analysis updated", "Your tariff and estimated usage have been recalculated.");
  });
  $("#billPhoto").addEventListener("change", event => {
    const file = event.target.files[0];
    if (!file) return;
    $("#billDropzone strong").textContent = file.name;
    $("#billDropzone small").textContent = "Ready to review extracted values";
    showToast("Bill received", "Demo OCR values are ready for your confirmation.");
  });
  $("#schemeForm").addEventListener("submit", event => {
    event.preventDefault();
    renderSchemes($("#consumerCategory").value, Number($("#monthlyUnits").value));
    showToast("Eligibility refreshed", "Schemes were matched to your selected category.");
  });
  $("#incidentTableBody").addEventListener("click", event => {
    const button = event.target.closest("[data-advance-report]");
    if (button) advanceReport(Number(button.dataset.advanceReport));
  });
  $("#voiceDemoButton").addEventListener("click", () => {
    $("#voiceTranscript").textContent = state.language === "te" ? "“నా ప్రాంతంలో కరెంట్ లేదు”" : "“There is no power in my area”";
    setTimeout(() => { closeModals(); navigate("map"); showToast("Vaani understood", "Opening PowerPulse for your area."); }, 900);
  });
  document.addEventListener("keydown", event => { if (event.key === "Escape") closeModals(); });
}

function init() {
  bindEvents(); applyLanguage(); renderReports(); renderMap(); renderAppliances(); renderSchemes(); switchRole(state.role);
  const initialView = location.hash.slice(1);
  if (["home", "report", "map", "bill", "schemes"].includes(initialView)) navigate(initialView);
}

init();
